/**
 * Errors returned by the shared store FFI.
 */
public enum SharedStoreError {

    
    
    case NotFound(message: String
    )
    case AlreadyExists(message: String
    )
    case InvalidArgument(message: String
    )
    case Storage(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSharedStoreError: FfiConverterRustBuffer {
    typealias SwiftType = SharedStoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SharedStoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .AlreadyExists(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SharedStoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NotFound(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .AlreadyExists(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidArgument(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


extension SharedStoreError: Equatable, Hashable {}

extension SharedStoreError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

